def longest_unique(codes):
    last = {}          # char -> most recent index
    left = 0
    best = 0
    for right, ch in enumerate(codes):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1
        last[ch] = right
        best = max(best, right - left + 1)
    return best

javascript.solution:
function longestUnique(codes) {
  const last = new Map();          // char -> most recent index
  let left = 0;
  let best = 0;
  for (let right = 0; right < codes.length; right++) {
    const ch = codes[right];
    if (last.has(ch) && last.get(ch) >= left) left = last.get(ch) + 1;
    last.set(ch, right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}
